# Find all rectangular blocks of 2s and their potential corners
def find_rectangles(grid):
    """Find all maximal rectangular blocks of 2s"""
    rows, cols = grid.shape
    blocks = []

    for r in range(rows):
        for c in range(cols):
            if grid[r, c] == 2:
                # Find the rectangle
                r1, c1 = r, c
                r2, c2 = r, c

                # Expand down
                while r2 + 1 < rows and grid[r2 + 1, c1] == 2 and grid[r2 + 1, c2] == 2:
                    r2 += 1
                    # Expand right
                    while c2 + 1 < cols and grid[r2, c2 + 1] == 2:
                        c2 += 1
                        # Expand down from here
                        rr = r2
                        while rr + 1 < rows and grid[rr + 1, c1] == 2 and grid[rr + 1, c2] == 2:
                            rr += 1
                            c2 += 1
                            while c2 + 1 < cols and grid[rr, c2 + 1] == 2:
                                c2 += 1
                blocks.append(((r1, c1), (r2, c2)))

    return blocks

blocks = find_rectangles(grid)
print(f"Found {len(blocks)} blocks")
for i, ((r1, c1), (r2, c2)) in enumerate(blocks):
    print(f"Block {i}: rows {r1}-{r2}, cols {c1}-{c2}")

